//! App icon and desktop metadata (M6-04). The master is `assets/app-icon/icon.svg`; the PNG
//! sizes, `icon.ico` and `icon.icns` next to it are generated by
//! `scripts/app-icon.sh` (the ignored test `generate_app_icons` below).

/// The 256 px PNG, used as window icon.
const WINDOW_ICON_PNG: &[u8] = include_bytes!("../assets/app-icon/icon-256.png");

/// Window icon for the main and the askpass window; `None` if decoding fails.
pub fn window_icon() -> Option<iced::window::Icon> {
    let image = image::load_from_memory_with_format(WINDOW_ICON_PNG, image::ImageFormat::Png)
        .ok()?
        .to_rgba8();
    let (width, height) = image.dimensions();
    iced::window::icon::from_rgba(image.into_raw(), width, height).ok()
}

/// Window settings shared by all windows: icon and, on Linux, the
/// application id that matches the `.desktop` file (Wayland taskbar icon).
pub fn window_settings(size: iced::Size) -> iced::window::Settings {
    #[allow(unused_mut)]
    let mut settings = iced::window::Settings {
        size,
        icon: window_icon(),
        ..iced::window::Settings::default()
    };
    #[cfg(target_os = "linux")]
    {
        settings.platform_specific.application_id = git_core::identity::APP_ID.to_owned();
    }
    settings
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    /// PNG sizes written next to the master.
    const SIZES: [u32; 9] = [16, 24, 32, 48, 64, 128, 256, 512, 1024];

    /// Sizes inside `icon.ico` (Windows uses up to 256).
    const ICO_SIZES: [u32; 7] = [16, 24, 32, 48, 64, 128, 256];

    /// `icon.icns` entries: OSType and pixel size (PNG payloads).
    const ICNS_TYPES: [(&[u8; 4], u32); 10] = [
        (b"icp4", 16),
        (b"icp5", 32),
        (b"icp6", 64),
        (b"ic07", 128),
        (b"ic08", 256),
        (b"ic09", 512),
        (b"ic10", 1024),
        (b"ic11", 32),
        (b"ic12", 64),
        (b"ic13", 256),
    ];

    fn dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("assets/app-icon")
    }

    fn render(svg: &[u8], size: u32) -> Vec<u8> {
        let tree = resvg::usvg::Tree::from_data(svg, &resvg::usvg::Options::default()).unwrap();
        let mut pixmap = resvg::tiny_skia::Pixmap::new(size, size).unwrap();
        let scale = size as f32 / tree.size().width();
        resvg::render(
            &tree,
            resvg::tiny_skia::Transform::from_scale(scale, scale),
            &mut pixmap.as_mut(),
        );
        pixmap.encode_png().unwrap()
    }

    /// ICO with PNG entries (supported since Windows Vista).
    fn ico(entries: &[(u32, Vec<u8>)]) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(&0u16.to_le_bytes());
        out.extend_from_slice(&1u16.to_le_bytes());
        out.extend_from_slice(&(entries.len() as u16).to_le_bytes());
        let mut offset = 6 + 16 * entries.len() as u32;
        for (size, png) in entries {
            let side = if *size >= 256 { 0 } else { *size as u8 };
            out.extend_from_slice(&[side, side, 0, 0]);
            out.extend_from_slice(&1u16.to_le_bytes());
            out.extend_from_slice(&32u16.to_le_bytes());
            out.extend_from_slice(&(png.len() as u32).to_le_bytes());
            out.extend_from_slice(&offset.to_le_bytes());
            offset += png.len() as u32;
        }
        for (_, png) in entries {
            out.extend_from_slice(png);
        }
        out
    }

    /// ICNS with PNG payloads.
    fn icns(entries: &[(&[u8; 4], Vec<u8>)]) -> Vec<u8> {
        let mut body = Vec::new();
        for (kind, png) in entries {
            body.extend_from_slice(*kind);
            body.extend_from_slice(&(png.len() as u32 + 8).to_be_bytes());
            body.extend_from_slice(png);
        }
        let mut out = b"icns".to_vec();
        out.extend_from_slice(&(body.len() as u32 + 8).to_be_bytes());
        out.extend_from_slice(&body);
        out
    }

    #[test]
    #[ignore = "regenerates the icon files; run scripts/app-icon.sh"]
    fn generate_app_icons() {
        let svg = std::fs::read(dir().join("icon.svg")).unwrap();
        for size in SIZES {
            std::fs::write(dir().join(format!("icon-{size}.png")), render(&svg, size)).unwrap();
        }
        let ico_entries: Vec<_> = ICO_SIZES.iter().map(|&s| (s, render(&svg, s))).collect();
        std::fs::write(dir().join("icon.ico"), ico(&ico_entries)).unwrap();
        let icns_entries: Vec<_> = ICNS_TYPES
            .iter()
            .map(|&(kind, s)| (kind, render(&svg, s)))
            .collect();
        std::fs::write(dir().join("icon.icns"), icns(&icns_entries)).unwrap();
    }

    #[test]
    fn generated_files_exist_with_their_sizes() {
        for size in SIZES {
            let data = std::fs::read(dir().join(format!("icon-{size}.png"))).unwrap();
            let image = image::load_from_memory(&data).unwrap();
            assert_eq!((image.width(), image.height()), (size, size));
        }
        let ico = std::fs::read(dir().join("icon.ico")).unwrap();
        assert_eq!(&ico[..4], &[0, 0, 1, 0]);
        assert_eq!(
            u16::from_le_bytes([ico[4], ico[5]]) as usize,
            ICO_SIZES.len()
        );
        let icns = std::fs::read(dir().join("icon.icns")).unwrap();
        assert_eq!(&icns[..4], b"icns");
        assert_eq!(
            u32::from_be_bytes([icns[4], icns[5], icns[6], icns[7]]) as usize,
            icns.len()
        );
    }

    #[test]
    fn container_layouts() {
        let ico = ico(&[(16, vec![1, 2]), (256, vec![3])]);
        // Header, two directory entries, payloads.
        assert_eq!(ico.len(), 6 + 32 + 3);
        assert_eq!(ico[6], 16);
        assert_eq!(ico[22], 0, "256 px is stored as 0");
        assert_eq!(u32::from_le_bytes([ico[18], ico[19], ico[20], ico[21]]), 38);
        let icns = icns(&[(b"ic07", vec![9; 4])]);
        assert_eq!(icns.len(), 8 + 8 + 4);
        assert_eq!(&icns[8..12], b"ic07");
        assert_eq!(
            u32::from_be_bytes([icns[12], icns[13], icns[14], icns[15]]),
            12
        );
    }

    /// The packaging metadata (`packaging/`) spells the identity values;
    /// they must match `git_core::identity` (ADR-028).
    #[test]
    fn packaging_metadata_matches_identity() {
        use git_core::identity::{APP_ID, BINARY_NAME, DISPLAY_NAME, ISSUES_URL, REPOSITORY_URL};
        let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../packaging");
        let desktop =
            std::fs::read_to_string(root.join(format!("linux/{APP_ID}.desktop"))).unwrap();
        for line in [
            format!("Name={DISPLAY_NAME}"),
            format!("Exec={BINARY_NAME} %F"),
            format!("Icon={APP_ID}"),
            format!("StartupWMClass={APP_ID}"),
            "Categories=Development;RevisionControl;".to_owned(),
        ] {
            assert!(desktop.lines().any(|l| l == line), "missing {line}");
        }
        assert!(!desktop.contains("MimeType"));
        let metainfo =
            std::fs::read_to_string(root.join(format!("linux/{APP_ID}.metainfo.xml"))).unwrap();
        for part in [
            format!("<id>{APP_ID}</id>"),
            format!("<name>{DISPLAY_NAME}</name>"),
            format!("<launchable type=\"desktop-id\">{APP_ID}.desktop</launchable>"),
            format!("<binary>{BINARY_NAME}</binary>"),
            format!("<url type=\"homepage\">{REPOSITORY_URL}</url>"),
            format!("<url type=\"bugtracker\">{ISSUES_URL}</url>"),
            "<project_license>GPL-3.0-or-later</project_license>".to_owned(),
        ] {
            assert!(metainfo.contains(&part), "missing {part}");
        }
        let manifest =
            std::fs::read_to_string(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("Cargo.toml"))
                .unwrap();
        assert!(manifest.contains(&format!("productName = \"{DISPLAY_NAME}\"")));
        assert!(manifest.contains(&format!("identifier = \"{APP_ID}\"")));
        let appimage = std::fs::read_to_string(root.join("linux/appimage.desktop")).unwrap();
        assert!(appimage.contains(&format!("StartupWMClass={APP_ID}")));
        let plist = std::fs::read_to_string(root.join("macos/Info.plist")).unwrap();
        assert!(plist.contains(&format!("<string>{APP_ID}</string>")));
        assert!(plist.contains(&format!("<string>{DISPLAY_NAME}</string>")));
        assert!(plist.contains("<key>NSHighResolutionCapable</key>"));
    }

    #[test]
    fn window_icon_decodes() {
        assert!(window_icon().is_some());
        let settings = window_settings(iced::Size::new(100.0, 100.0));
        assert!(settings.icon.is_some());
    }
}
